mapper.select:
SELECT * FROM (
WHERE s.status = 1 AND s.name LIKE CONCAT('%', #{name}, '%')
AND (s.category_id = #{categoryId} OR s.category_id IN (SELECT id FROM t_category WHERE parent_id = #{categoryId} AND status = 1))
) t
AND t.min_price >= #{minPrice} AND t.min_price <= #{maxPrice}
ORDER BY t.min_price ASC ORDER BY t.min_price DESC ORDER BY t.sales_count DESC ORDER BY t.create_time DESC ORDER BY t.id DESC


WHERE s.status = 1
ORDER BY s.sales_count DESC, s.id DESC
LIMIT #{limit}


WHERE s.status = 1
  AND s.category_id = (SELECT category_id FROM t_spu WHERE id = #{spuId} AND status = 1)
  AND s.id != #{spuId}
ORDER BY s.sales_count DESC, s.id DESC
LIMIT #{limit}

WHERE s.status = 1 AND s.category_id IN ( SELECT category_id FROM ( SELECT DISTINCT category_id FROM t_spu WHERE status = 1 AND name LIKE CONCAT('%', #{keyword}, '%') LIMIT 5 ) viewed_categories )
AND s.name NOT LIKE CONCAT('%', #{keyword}, '%')
ORDER BY s.sales_count DESC, s.id DESC LIMIT #{limit}


WHERE s.status = 1 AND s.id IN

    #{id}

ORDER BY FIELD(s.id,

    #{id}

)


WHERE s.status = 1 AND s.category_id = #{categoryId}
ORDER BY s.sales_count DESC, s.id DESC
LIMIT #{limit}
